def make_pages(c,button,video):
 def hero(kicker,title,lead):return f'<div class="wrap"><section class="pagehero"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{lead}</p></section>'
 def article(kicker,title,lead,body):return hero(kicker,title,lead)+'<div class="article">'+body+'</div></div>'
 pages=[]
 def add(path,title,desc,body):
  photos={
   '/about/':('rob-outdoors-portrait','Rob Sarison outdoors on a hillside overlooking the coast','A creative perspective, in and beyond the therapy room.'),
   '/drama-therapy/':('rob-creative','Robert Sarison holding a microphone in front of a rainbow backdrop','Imagination, playfulness, and the possibility of trying something new.'),
   '/psychotherapy/':('therapy-notebook','A wooden pencil resting on a blank notebook','Space to reflect. Room to try something different.'),
   '/psychotherapy/approach/':('therapy-notebook','A blank notebook and wooden pencil','Understanding your experience. Exploring your next steps.'),
   '/training-consultation/':('rob-presentation','An audience watching Robert Sarison on a conference presentation screen','Leadership, education, and training: sharing ideas with a professional audience.'),
  }
  if path in photos:
   name,alt,caption=photos[path]
   image=f'<figure class="page-photo {name}"><img src="/{name}-1200.webp" srcset="/{name}-600.webp 600w, /{name}-1200.webp 1200w" sizes="(max-width:800px) 88vw, 42vw" alt="{alt}" width="1200" height="{800 if name=='therapy-notebook' else 1361 if name=='rob-creative' else 900 if name=='rob-presentation' else 1500}"><figcaption>{caption}</figcaption></figure>'
   begin=body.index('<section class="pagehero">');end=body.index('</section>',begin)
   hero=body[begin+len('<section class="pagehero">'):end]
   body=body[:begin]+'<section class="pagehero photo-hero"><div class="photo-hero-copy">'+hero+'</div>'+image+'</section>'+body[end+len('</section>'):]
  pages.append((path,title,desc,body))
 add('/about/','About Rob','Meet Rob Sarison, LMFT, RDT: an experienced, active psychotherapist with a background in creative approaches, dementia care, teaching and leadership.',article('About Rob','A practical mind.<br>A creative perspective.','I’m Rob Sarison, LMFT, RDT. I bring warmth, directness, and curiosity to the work of helping people make meaningful changes.', '''<h2>The relationship comes first.</h2><p>Therapy works best when we can speak honestly, ask useful questions, and stay curious about what is possible. I take an active role: helping you notice patterns, consider different perspectives, and practice ways of responding that fit the life you want to build.</p><p>I work with individuals, couples, and families. We may focus on anxiety or low mood, a relationship that feels stuck, a difficult transition, grief, or a recurring conflict. Your priorities help shape our work.</p><p>My clinical expertise also includes working with the LGBTQ+ community. I offer affirming support for identity, relationships, belonging, and life transitions, grounded in respect for each person’s lived experience.</p><h2>Clinical expertise. Executive leadership. Human connection.</h2><p>My career spans clinical practice, senior executive leadership, and professional education, with particular expertise in aging and dementia care. I have held senior leadership roles at the San Francisco Campus for Jewish Living, including Executive Director of Frank Residences, and led the Irene Swindells Alzheimer’s Residential Care Program at California Pacific Medical Center.</p><p>These experiences give me a broad perspective on the challenges facing older adults, families, caregivers, and the organizations that serve them. In my therapy practice, I bring that depth of experience to the personal realities of changing relationships, difficult decisions, and finding a way forward.</p><h2>Experience shared with others.</h2><p>Alongside clinical and leadership work, I have supervised and trained therapists and other helping professionals, and presented at professional conferences, educational seminars, and workshops. Teaching means making complex ideas useful—a quality I also bring to therapy.</p><p>In my private practice, these experiences inform a collaborative, grounded approach. My wider career is part of what I bring into the room; the focus of our sessions remains you.</p><h2>Meet Rob on video.</h2>'''+video()+'''<h2>Professional credentials</h2><p>Licensed Marriage and Family Therapist (LMFT)<br>Registered Drama Therapist (RDT)</p><p><a href="/psychotherapy/approach/">Explore my therapeutic approach</a></p>'''))
 subnav='<nav class="subnav" aria-label="Psychotherapy topics"><a href="/psychotherapy/individual/">Individuals</a><a href="/psychotherapy/couples/">Couples</a><a href="/psychotherapy/family/">Families</a><a href="/psychotherapy/approach/">My approach</a><a href="/psychotherapy/cbt-dbt/">CBT & DBT approaches</a></nav>'
 add('/psychotherapy/','Psychotherapy in the San Francisco Bay Area','Individual, couples and family psychotherapy with an active, practical approach. Support for relationships, anxiety, low mood, grief and life transitions.',hero('Psychotherapy','Understand the pattern.<br>Make room for change.','Individual, couples, and family therapy that connects what you learn in the room with what you do in everyday life.')+subnav+'''<div class="article"><h2>We start with what matters to you.</h2><p>You don’t need a perfectly defined problem to begin. We’ll talk about what brings you here, what you have already tried, and what you would like to be different.</p><h3><a href="/psychotherapy/individual/">Individual therapy</a></h3><p>Space to examine your experience, strengthen coping skills, and change patterns that leave you feeling stuck.</p><h3><a href="/psychotherapy/couples/">Couples therapy</a></h3><p>Work together on communication, conflict, connection, and the decisions that shape your relationship.</p><h3><a href="/psychotherapy/family/">Family therapy</a></h3><p>Understand each other more clearly and develop more workable ways of handling conflict, caregiving, and changing roles.</p><h2>LGBTQ+ affirming therapy</h2><p>I bring particular expertise in working with the LGBTQ+ community, offering affirming care that respects your identity, relationships, and lived experience. Our work can address identity and belonging, relationships and family dynamics, the impact of stigma or discrimination, and major life transitions.</p><p>You may also be seeking support for anxiety, grief, or everyday challenges. Your priorities guide our work, with room for the full complexity of who you are.</p><h2>Clear goals. Room for complexity.</h2><p>We’ll identify goals that are meaningful to you and check in about progress. Some changes may be concrete, such as handling a difficult conversation differently. Others may involve recognizing emotions earlier or responding to yourself with greater understanding. Therapy is individualized; outcomes and pace vary.</p></div></div>''')
 services=[('individual','Individual therapy','A different relationship<br>with yourself.','When worry, low mood, grief, or recurring patterns are taking up too much of your life, therapy can help you examine what is happening and try a different response.','You may be navigating a transition, struggling in relationships, or feeling caught between what you understand and what you can change. We’ll work to make your experience more understandable and your next steps more manageable.',['Recognizing thought and behavior patterns that contribute to distress','Building emotional regulation and coping skills','Working through grief, loss, and changing roles','Clarifying boundaries, priorities, and relationship needs'],'An active partnership','We’ll combine thoughtful conversation with practical strategies. Depending on your goals, that may include noticing automatic thoughts, rehearsing a difficult conversation, or experimenting with a new response between sessions.'),('couples','Couples therapy','Beyond the<br>same argument.','A relationship can matter deeply and still feel difficult. Therapy offers a structured way to understand what happens between you and practice something different.','When conversations turn into familiar arguments, it can be hard to hear the concern underneath each person’s words. We’ll slow down the pattern, examine how you affect one another, and work toward clearer, more constructive communication.',['Recognizing recurring cycles of conflict or withdrawal','Expressing needs and listening more effectively','Navigating transitions and changing expectations','Exploring connection, boundaries, and difficult decisions'],'Work that includes both of you','Our work will make room for different perspectives without assuming you must agree on everything. We’ll identify shared goals where possible and explore what a healthier relationship would mean for each of you. A consultation helps us consider whether couples work is appropriate for your situation.'),('family','Family therapy','Different perspectives.<br>A shared way forward.','Family relationships can become strained when needs, expectations, and responsibilities change. You can work on the pattern together.','Family therapy looks beyond a single person as “the problem.” We’ll explore the interactions, roles, and expectations that keep conflict going, while paying attention to each person’s experience.',['Improving communication during conflict','Clarifying boundaries and responsibilities','Navigating aging, caregiving, and family decisions','Responding to grief, loss, and major transitions'],'A more workable conversation','We’ll discuss who should participate and what each person hopes to change. Sessions may focus on slowing down difficult conversations, identifying unspoken expectations, and practicing clearer ways of asking for and offering support.')]
 for slug,label,title,lead,intro,items,h,txt in services:
  body=hero(label,title,lead)+subnav+'<div class="article"><p>'+intro+'</p><h2>What we might work on</h2><ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul><h2>'+h+'</h2><p>'+txt+'</p><p>Available through California telehealth. Discuss current arrangements and availability during a consultation.</p></div></div>'
  if slug=='individual':body=body.replace('<h2>What we might work on</h2>','<h2>Affirming support for LGBTQ+ clients</h2><p>I bring particular expertise in working with LGBTQ+ clients. We can explore identity, belonging, relationships, family expectations, and life transitions in a space that respects who you are. Whether these experiences are central to what brings you to therapy or part of the wider context, we’ll focus on what matters to you.</p><h2>What we might work on</h2>')
  add('/psychotherapy/'+slug+'/',label+' in California',lead.replace('<br>',' '),body)
 add('/psychotherapy/approach/','Therapeutic Approach','An integrative approach to psychotherapy: practical CBT and DBT-informed strategies, family systems, relational work and creative experiential techniques.',hero('My therapeutic approach','Insight, put<br>into practice.','Therapy is a collaboration. I bring clinical perspective and practical tools; you bring your experience, priorities, and knowledge of your own life.')+subnav+'''<div class="article"><h2>Active, direct, and responsive.</h2><p>I listen closely, ask questions, and help you make connections. We’ll consider both the history of a pattern and what you can do differently now. Together, we’ll set goals and revisit whether the work is helping.</p><h2>Different tools for different needs.</h2><h3>CBT and DBT-informed strategies</h3><p>We may examine how thoughts, feelings, and behaviors reinforce each other, or practice skills for managing strong emotions, tolerating distress, and communicating more effectively. <a href="/psychotherapy/cbt-dbt/">Read about CBT and DBT approaches</a>.</p><h3>Family systems and relational psychotherapy</h3><p>Our relationships shape us. We’ll look at the roles, expectations, and interactions that influence your experience, including patterns that show up across relationships.</p><h3>Experiential work and drama therapy</h3><p>Sometimes it helps to try a new response, rather than only describe it. Role work, imagination, storytelling, and perspective taking can offer another route into understanding and change. Exercises are collaborative and adapted to your comfort. <a href="/drama-therapy/">Learn about drama therapy</a>.</p><h2>Progress that means something to you.</h2><p>We may track changes in mood, coping, communication, or specific situations. Regular check-ins help us adjust our focus. There is no single timetable or guaranteed outcome; the aim is useful, meaningful progress.</p></div></div>''')
 add('/psychotherapy/cbt-dbt/','CBT & DBT-Informed Therapy','Understand CBT and DBT-informed strategies in plain language: thought patterns, emotional regulation, coping skills and more effective communication.',article('Tools for everyday life','Practical skills.<br>Thoughtful application.','I draw from CBT and DBT approaches as part of integrative psychotherapy, tailoring the work to your goals.', '''<h2>CBT: understand the connections.</h2><p>Cognitive Behavioral Therapy (CBT) examines the connections among thoughts, emotions, and behaviors. A thought such as “I’ll get this wrong” might lead to anxiety and avoidance. Avoidance may then keep the worry going.</p><p>We can explore whether a thought is useful or accurate, consider alternatives, and try manageable changes in behavior. The goal is not to replace every difficult thought with a positive one. It is to develop more flexible responses.</p><h2>DBT-informed strategies: respond with more choice.</h2><p>Dialectical Behavior Therapy (DBT) offers practical skills that can be integrated into our work:</p><ul><li><strong>Emotional regulation:</strong> noticing feelings earlier and choosing how to respond.</li><li><strong>Distress tolerance:</strong> getting through difficult moments without making them harder.</li><li><strong>Interpersonal effectiveness:</strong> expressing needs, setting boundaries, and navigating disagreement.</li><li><strong>Mindful awareness:</strong> noticing what is happening before reacting automatically.</li></ul><h2>Part of a broader approach.</h2><p>I integrate CBT and DBT-informed strategies with relational, family systems, and experiential work. This is not presented as a comprehensive DBT program or a claim of CBT or DBT certification.</p><p><a href="/psychotherapy/approach/">Return to my therapeutic approach</a></p>'''))
 add('/aging-memory-caregiving/','Aging, Memory Loss & Family Caregiving','Psychotherapy, family support, education and consultation for aging, memory loss, caregiver stress, changing roles, grief and difficult care decisions.',article('Aging, Dementia &amp; Family Caregiving','Care for the relationship.<br>Support for the changes.','When memory or independence changes, the emotional impact reaches well beyond one person. Support can include you, too.', '''<h2>You don’t have to make sense of it alone.</h2><p>A diagnosis can change the way a family thinks about the future. Spouses, partners, adult children, and other caregivers may find themselves balancing love, exhaustion, uncertainty, and difficult decisions.</p><p>I offer psychotherapy, family support, education, and consultation for people adjusting to cognitive changes and for the people close to them. We can work on the emotional and relational challenges while keeping dignity, identity, and connection in view.</p><h2>Practical support for complicated situations.</h2><ul><li>Adjusting to a diagnosis or a transition in care</li><li>Caregiver stress, changing roles, and personal limits</li><li>Family conflict over responsibilities and care decisions</li><li>Communication and understanding behavioral changes</li><li>Anticipatory grief, loss, and mixed feelings</li><li>Maintaining connection, meaning, and quality of life</li></ul><h2>Experience that informs the work.</h2><p>Aging and dementia care have been a significant focus of my professional career. I am a Dementia Capable Care Specialist (DCCS) through the Crisis Prevention Institute and have led extensive trainings and workshops for healthcare professionals, employees, and family caregivers. I have presented at conferences and professional programs for organizations including the Alzheimer’s Association and Institute on Aging, and have served as a provider for Family Caregiver Alliance.</p><p>I bring this experience together with my background as a family therapist to help older adults and their families navigate the emotional and relational dimensions of aging and dementia—from changing relationships and caregiver stress to difficult decisions and family disagreements about care.</p><p><strong>Dementia changes relationships. It doesn’t diminish the need for connection, dignity, creativity, and meaning.</strong></p><p>My professional background includes leadership of the Irene Swindells Alzheimer’s Residential Care Program at California Pacific Medical Center and senior leadership at the San Francisco Campus for Jewish Living, including Executive Director of Frank Residences.</p><p>That experience informs attention to the whole person: remaining abilities, creativity, relationships, and what continues to bring meaning. The work is grounded in the challenges families actually face.</p><div class="notice"><p><strong>A clear role.</strong> These services provide psychotherapy, family support, education, and consultation. They do not include neurological diagnosis or medical treatment of dementia. Medical questions belong with your physician or specialist.</p></div><h2>See creative dementia care in practice.</h2><p>In “Play’s the Thing!” at the Creative Arts and Dementia Symposium, Rob demonstrates his creative approach to dementia care. Watch the complete presentation, shared by the Alzheimer’s Association California &amp; Nevada.</p>'''+video(1)+'''<p>Professionals and organizations can also explore <a href="/training-consultation/">training and consultation</a>.</p>'''))
 add('/drama-therapy/','Drama Therapy in the San Francisco Bay Area','Drama therapy with Rob Sarison, RDT. Creative, experiential ways to explore relationships, emotions and new responses. No acting experience necessary.',article('Drama therapy','Sometimes talking<br>is only the beginning.','Creative approaches can help you explore an experience from a different angle—and practice what a new response might feel like.', '''<h2>No acting experience is necessary.</h2><p>Drama therapy is not about putting on a performance. It uses elements such as role work, storytelling, imagination, improvisation, and perspective taking to support therapeutic goals.</p><p>You don’t need to be outgoing, theatrical, or especially “creative.” We decide together whether an exercise would be useful. You can ask questions, adapt it, or choose another way of working.</p><h2>What might it look like?</h2><h3>Rehearse a conversation.</h3><p>Try saying what you need to say to someone important, notice what gets in the way, and experiment with another approach.</p><h3>Explore a familiar role.</h3><p>Consider a role you often find yourself in—such as the peacemaker or the person who handles everything—and explore other possibilities.</p><h3>Try another perspective.</h3><p>Use an imagined scene or a story to consider an experience with a little more distance, curiosity, or flexibility.</p><h2>One part of an integrative practice.</h2><p>As a Registered Drama Therapist (RDT), I bring creative and experiential tools into psychotherapy when they fit your needs. They can complement conversation, CBT and DBT-informed skills, and relational work.</p><p><a href="/psychotherapy/approach/">Explore the full therapeutic approach</a></p>'''))
 add('/training-consultation/','Training & Consultation','Professional training, workshops and consultation on dementia-capable care, family caregiving, communication, drama therapy and experiential techniques.',article('For professionals & organizations','Ideas that become<br>useful practice.','Training and consultation for people whose work is supporting other people.', '''<h2>Leadership, education &amp; training</h2><p>Aging and dementia care have been a significant focus of my professional career. I am a Dementia Capable Care Specialist (DCCS) through the Crisis Prevention Institute and have led extensive trainings and workshops for healthcare professionals, employees, and family caregivers. I have presented at conferences and professional programs for organizations including the Alzheimer’s Association and Institute on Aging, and have served as a provider for Family Caregiver Alliance.</p><h2>Clinical perspective. Practical application.</h2><p>My experience includes supervising and training therapists and helping professionals, as well as presenting at conferences, educational seminars, and workshops. I connect clinical ideas with the situations participants face in their everyday work.</p><h2>Possible topics</h2><ul><li>Dementia-capable care and meaningful engagement</li><li>Communication, connection, and creativity in dementia care</li><li>Family dynamics, caregiver stress, and conflict</li><li>Drama therapy and experiential techniques</li><li>Therapeutic improvisation and perspective taking</li><li>Professional development for helping professionals</li></ul><h2>Who this work is for</h2><p>Therapists, healthcare professionals, senior-living and memory-care organizations, caregiver groups, professional associations, and conference organizers.</p><h2>Begin with the needs of your group.</h2><p>We can discuss your audience, the challenges you want to address, and an appropriate format. Possible formats include workshops, educational seminars, presentations, and consultation. Scope, availability, and fees are agreed in advance.</p><p>For family support around a personal situation, visit <a href="/aging-memory-caregiving/">aging, memory loss & family caregiving</a>. For a professional inquiry, use the <a href="/contact/#inquiry">inquiry option</a>.</p>'''))
 fees=''.join('<details class="faq"><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in [
 ('How much does therapy cost?','Session fees are not yet published. Fees, session length, and payment arrangements will be discussed before you begin, so you can make an informed decision.'),
 ('Do you accept insurance?','This is a private-pay practice. I can provide appropriate documentation or a superbill that clients with eligible PPO or out-of-network benefits may submit to their insurer. Reimbursement is not guaranteed. Please confirm eligibility, deductibles, documentation requirements, and reimbursement directly with your plan.'),
 ('Is telehealth available?','California telehealth is part of the practice. We will confirm your location, suitability for telehealth, and current appointment availability before starting.'),
 ('Can I meet in person?','In-person arrangements and the office location have not yet been published. Ask about current options during your consultation.'),
 ('What happens in a consultation?','We’ll discuss what brings you to therapy, what you’re looking for, and any practical questions. It is an opportunity for both of us to consider fit. The consultation’s length and any fee will be confirmed when scheduling.'),
 ('Do I have to do drama therapy?','No. Creative or experiential exercises are an option within an integrative approach. We decide together what is useful and comfortable for you.'),
 ('How long will therapy take?','The length and frequency depend on your needs, goals, and circumstances. We’ll discuss a starting plan and review progress together. No particular outcome or timeline is guaranteed.'),
 ('What is the cancellation policy?','The practice’s cancellation policy will be provided before you book ongoing sessions.'),
 ('Does sending an inquiry make me a client?','No. Sending an inquiry or requesting a consultation does not establish a therapist-client relationship. Services begin only after we agree to work together and complete the required arrangements.')])
 configured_fees=''.join('<p>'+k.title()+': '+str(v)+'</p>' for k,v in c['fees'].items() if v)
 add('/fees-faq/','Fees & Frequently Asked Questions','Private-pay therapy, superbills and out-of-network benefits, California telehealth, consultations and practical questions about getting started.',article('Fees & FAQ','Clear expectations.<br>Thoughtful decisions.','Understanding the practical details is part of finding a good fit.','<h2>A private-pay practice.</h2><p>Payment is made directly to the practice. We’ll discuss fees and arrangements before beginning therapy.</p>'+configured_fees+fees))
 contact=hero('Contact','Let’s start with<br>a conversation.','Contact me by email or phone to discuss your needs and arrange a consultation. I handle all scheduling directly.')+'<div class="contact-grid"><section class="contact-card" id="consultation"><h2>Email me</h2><p>Send a brief introduction or ask about a consultation.</p><p><a href="mailto:robsarison@gmail.com">robsarison@gmail.com</a></p></section><section class="contact-card" id="inquiry"><h2>Call me</h2><p>Prefer to speak by phone? Call to discuss your needs and arrange a time to talk.</p><p><a href="tel:4156131946">415.613.1946</a></p>'+button('Call 415.613.1946','tel:4156131946')+'</section></div><div class="article"><h2>Scheduling is personal.</h2><p>After we connect by email or phone, we’ll discuss whether working together feels like a good fit and arrange a time directly. There is no online booking calendar.</p><p>San Francisco Bay Area · California telehealth</p><div class="notice"><p>Please keep email inquiries brief and leave sensitive clinical details for a private conversation. Contacting me does not establish a therapist-client relationship.</p></div><h2>Need immediate support?</h2><p>Email and phone inquiries are not monitored for emergencies. If you are in immediate danger, call 911. In the U.S., call or text <a href="tel:988">988</a> for crisis support.</p></div></div>'
 add('/contact/','Contact & Consultation Inquiries','Email or call Robert Sarison to discuss your needs and arrange a consultation directly.',contact)
 add('/client-portal/','Contact Robert Sarison','Please contact Robert Sarison directly by email or phone for scheduling.',article('Contact & scheduling','Please contact me directly.','All appointments are arranged personally by email or phone.','<p><a href="mailto:robsarison@gmail.com">Email robsarison@gmail.com</a> or <a href="tel:4156131946">call 415.613.1946</a>.</p><p><a href="/contact/">Visit the contact page</a></p>'))
 add('/privacy/','Privacy & Website Information','How this website handles information, external services, video, inquiries and clinical boundaries.',article('Website information','Privacy, by design.','This website provides information about the practice. It is not a clinical record system.', '''<h2>Information and inquiries</h2><p>This site has no clinical intake form, advertising trackers, or analytics added by the practice. It does not store therapy notes, payment details, passwords, or inquiry submissions. Hosting providers may process technical information such as IP addresses and request logs to operate and secure the service.</p><h2>External services</h2><p>Initial consultation inquiries open your email application and are sent to robsarison@gmail.com. Please keep your message brief and leave sensitive clinical details for a private conversation. Consultations and appointments are arranged directly by email or phone. Those services operate under their own privacy policies and the practice’s clinical privacy notices.</p><p>YouTube videos load only when you activate the player. This connects to YouTube’s privacy-enhanced embed service; YouTube may then process information according to its policies. You may also choose to watch on YouTube directly.</p><h2>Clinical boundaries</h2><p>Website information is general and does not replace individual assessment or care. Visiting this site or submitting an inquiry does not establish a therapist-client relationship. The practice’s clinical privacy notices and informed-consent documents will be provided separately when services begin.</p><h2>Accessibility</h2><p>This site is designed for keyboard use, readable text, reduced motion preferences, and a range of screen sizes. If you have difficulty accessing information, please raise it through the practice’s contact channel when available.</p><h2>Photography</h2><p>Portrait, outdoor, creative-event, and presentation photographs supplied by Robert Sarison. Supporting notebook photograph by <a href="https://unsplash.com/photos/a-notebook-with-a-pen-on-top-of-it-1SBcc-Wpz40">Kelly Sikkema on Unsplash</a>.</p><p>San Francisco Bay photograph by <a href="https://unsplash.com/photos/golden-gate-bridge-san-francisco-mdXvWFaDBgw">Utsav Shah on Unsplash</a>, used under the <a href="https://unsplash.com/license">Unsplash License</a>.</p>'''))
 return pages
